import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"第五十九卦 渙 風水渙 巽上坎下","description":"周易 - 第五十九卦 渙 風水渙 巽上坎下","frontmatter":{"title":"第五十九卦 渙 風水渙 巽上坎下","description":"周易 - 第五十九卦 渙 風水渙 巽上坎下"},"headers":[],"relativePath":"classics/zhouyi/060.md","filePath":"classics/zhouyi/060.md"}'),l={name:"classics/zhouyi/060.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="渙" tabindex="-1">渙 <a class="header-anchor" href="#渙" aria-label="Permalink to “渙”">​</a></h1><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>亨。王假有廟，利涉大川，利貞。</p><h3 id="彖傳" tabindex="-1">彖傳 <a class="header-anchor" href="#彖傳" aria-label="Permalink to “彖傳”">​</a></h3><p>渙，亨。剛來而不窮，柔得位乎外而上同。王假有廟，王乃在中也。利涉大川，乘木有功也。</p><h3 id="象傳" tabindex="-1">象傳 <a class="header-anchor" href="#象傳" aria-label="Permalink to “象傳”">​</a></h3><p>風行水上，渙；先王以享於帝立廟。</p><h3 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h3><p>用拯馬壯，吉。象曰：初六之吉，順 也。</p><h3 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h3><p>渙奔其機，悔亡。象曰：渙奔其機，得願也。</p><h3 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h3><p>渙其躬，無悔。象曰：渙其躬，志在外也。</p><h3 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h3><p>渙其群，元吉。渙有丘，匪夷所思。象曰：渙其群，元吉；光大也。</p><h3 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h3><p>渙汗其大號，渙王居，無咎。象曰：王居無咎，正位也。</p><h3 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h3><p>渙其血，去逖出，無咎。象曰：渙其血，遠害也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
